namespace {
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
template<class F>void rejects(F f){bool rejected=false;try{f();}catch(const std::exception&e){rejected=true;std::cout<<"expected rejection: "<<e.what()<<'\n';}check(rejected,"corrupt result accepted");}
std::string read(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);check(bool(f),"missing test file");return {std::istreambuf_iterator<char>(f),{}};}
void same(const BatchResult&a,const BatchResult&b){check(a.route.hits()==b.route.hits()&&a.contact.hits()==b.contact.hits()&&a.contact.known()==b.contact.known()&&a.statistics.voxelHits()==b.statistics.voxelHits(),"recording/preview changed integer counts");check(a.trials.size()==b.trials.size()&&a.updates==b.updates,"recording changed physics update count");for(size_t i=0;i<a.trials.size();++i){const auto&x=a.trials[i];const auto&y=b.trials[i];check(x.input.values==y.input.values&&x.input.seed==y.input.seed&&x.last.reason==y.last.reason&&norm(x.last.center-y.last.center)==0&&norm(x.last.velocity-y.last.velocity)==0,"recording/preview changed physical result");const auto&u=*a.contacts[i];const auto&v=*b.contacts[i];check(u.status==v.status&&u.cell==v.cell&&u.timeLower==v.timeLower&&u.timeUpper==v.timeUpper&&u.u==v.u&&u.v==v.v,"recording/preview changed first event");}}
void checkArchive(const BatchResult&r){auto n=r.config->source.count;auto directory=readMotionDirectory(r.directory,n);auto contacts=readFirstContacts(r.directory,r.config->barrier,n,r.config->source.contactCell);FirstContactAccumulator reconstructed(r.config->barrier,n,r.config->source.contactCell);std::set<std::uint64_t> ids;
    for(size_t i=0;i<directory->trials.size();++i){auto t=directory->trials[i];check(t->id==i+1,"directory trial missing");if(!t->frames)continue;ids.insert(t->id);auto a=readMotionBlock(*directory,t->blocks.front()),b=readMotionBlock(*directory,t->blocks.back());check(a.front().snapshot.time==0&&norm(a.front().snapshot.center-r.trials[i].first.center)==0,"initial source state differs");check(b.back().snapshot.time==r.trials[i].last.time&&norm(b.back().snapshot.center-r.trials[i].last.center)==0&&b.back().snapshot.reason==r.trials[i].last.reason,"final source state differs");}
    for(const auto&e:contacts)reconstructed.finish(e);check(reconstructed.hits()==r.contact.hits()&&reconstructed.known()==r.contact.known(),"event CSV cannot reconstruct grid");
    readArchiveCsv(r.directory/"route_heatmap_xy.csv",r.route.hits().size(),[&](const CsvRow&row){auto id=archiveInteger(row.at("cell_id"));check(archiveInteger(row.at("H"))==r.route.hits().at(size_t(id)),"route CSV grid differs");});
    readArchiveCsv(r.directory/"barrier_first_contact_heatmap.csv",r.contact.hits().size(),[&](const CsvRow&row){auto id=archiveInteger(row.at("cell_id"));check(archiveInteger(row.at("H_b"))==r.contact.hits().at(size_t(id)),"first contact CSV grid differs");});
    auto complete=read(r.directory/"FILES_COMPLETE.txt");for(auto file:resultFiles)check(complete.find(std::string(file.name)+'\n')!=complete.npos&&std::filesystem::is_regular_file(r.directory/file.name),"registry missing completed file");validateResultFiles(r.directory,3);auto updatesBefore=physicsUpdateCount();auto opened=openResultArchive(r.directory);Session readonly(opened);MotionBlockCache cache(1024*1024);for(auto id:ids)check(cache.sample(*opened->analysis->directory,id,.013).available,"readonly block unavailable");check(physicsUpdateCount()==updatesBefore,"viewing archive advanced physics");check(opened->analysis->route->hits()==r.route.hits()&&opened->analysis->contact->hits()==r.contact.hits(),"independent read-only archive counts differ");for(auto id:ids){auto scene=opened->scene(id);check(scene->shape.vertices.size()==size_t(r.trials[size_t(id-1)].shapeDiagnostics.k)&&norm(scene->shape.center-r.trials[size_t(id-1)].canonicalCenter)==0,"read-only actual geometry differs");}std::cout<<"archive verified N="<<n<<" recorded_trial_ids="<<ids.size()<<" B="<<reconstructed.hitTrials()<<" M="<<reconstructed.missTrials()<<" unknown="<<reconstructed.unknown()<<'\n';
}
void put(const std::filesystem::path&p,const std::string&value){std::ofstream f(p,std::ios::binary|std::ios::trunc);f<<value;check(bool(f),"fixture write failed");}
void replaceField(const std::filesystem::path&p,const std::string&key,const std::string&value){auto text=read(p);auto start=text.find(key+"=");check(start!=text.npos,"missing fixture field");auto end=text.find('\n',start);text.replace(start,end-start,key+"="+value);put(p,text);}
void rows(const std::filesystem::path&p,const std::vector<CsvRow>&values){check(!values.empty(),"empty fixture rows");std::ostringstream out;for(auto row:{values.front()}){bool first=true;for(auto&f:row){if(!first)out<<',';out<<std::quoted(f.first);first=false;}out<<'\n';}for(auto&row:values){bool first=true;for(auto&f:row){if(!first)out<<',';out<<std::quoted(f.second);first=false;}out<<'\n';}put(p,out.str());}
void compatible(SceneDraft s,const std::filesystem::path&root){
    s.count=1;s.trajectoryStride=5;s.sourceSchema=1;BatchControl control;auto result=runBatch(freezeConfig(s),control);check(result.status==BatchStatus::complete,"legacy source fixture failed");
    for(int version:{1,2}){auto path=root/("legacy_"+std::to_string(version)+result.directory.filename().u8string());std::filesystem::copy(result.directory,path,std::filesystem::copy_options::recursive);replaceField(path/"manifest.ini","schema",std::to_string(version));
        auto before=physicsUpdateCount();auto archive=openResultArchive(path);check(archive->analysis->directory->legacy&&archive->analysis->directory->trials[0]->frames>0&&!archive->contactRecorded&&!archive->routeRecorded,"legacy view lost actual frames or invented analysis");check(archive->analysis->events[0]->status==FirstContactStatus::notRecorded,"legacy first contact inferred");Session view(archive);check(physicsUpdateCount()==before,"legacy view ran physics");
        if(version==1){auto registry=read(path/"FILES_COMPLETE.txt");for(auto name:{"barrier_trajectory.csv","barrier_trials.csv"}){std::filesystem::remove(path/name);auto at=registry.find(std::string(name)+'\n');if(at!=registry.npos)registry.erase(at,std::string(name).size()+1);}put(path/"FILES_COMPLETE.txt",registry);archive=openResultArchive(path);check(!archive->analysis->directory->legacyBarrier,"missing old barrier history fabricated");PlaybackReader reader;auto request=reader.request(archive->analysis->directory,1,.013,archive->config);std::shared_ptr<const PlaybackSample> sample;for(int attempt=0;attempt<5000;++attempt){sample=reader.latest();if(sample&&sample->request==request)break;std::this_thread::sleep_for(std::chrono::milliseconds(1));}check(sample&&sample->available&&norm(sample->snapshot.barrier.center-initialBarrierCenter(archive->config->barrier))==0,"missing legacy rigid board not restored from actual config");
            std::filesystem::remove(path/"trajectory.csv");auto at=registry.find("trajectory.csv\n");check(at!=registry.npos,"legacy registry fixture");registry.erase(at,15);put(path/"FILES_COMPLETE.txt",registry);archive=openResultArchive(path);check(!archive->analysis->directory->trials[0]->frames,"missing legacy trajectory fabricated");}
        std::cout<<"R2 independent schema="<<version<<" actual CSV / missing history / physics updates=0 PASS\n";
    }
    auto path=root/("large_geometry_"+result.directory.filename().u8string());std::filesystem::copy(result.directory,path,std::filesystem::copy_options::recursive);constexpr int ring=128;std::vector<Vec3>v;for(int i=0;i<ring;++i)v.push_back({2*std::cos(2*pi*i/ring),2*std::sin(2*pi*i/ring),0});v.push_back({0,0,2});v.push_back({0,0,-2});std::vector<Face>f;for(int i=0;i<ring;++i){f.push_back({i,(i+1)%ring,ring});f.push_back({(i+1)%ring,i,ring+1});}double volume=0;for(auto face:f)volume+=dot(v[face.a],cross(v[face.b],v[face.c]))/6;
    std::ostringstream vertices,faces;vertices<<std::setprecision(17)<<"trial_id,vertex_id,x,y,z\n";for(size_t i=0;i<v.size();++i)vertices<<1<<','<<i<<','<<v[i].x<<','<<v[i].y<<','<<v[i].z<<'\n';faces<<"trial_id,face_id,a,b,c\n";for(size_t i=0;i<f.size();++i)faces<<1<<','<<i<<','<<f[i].a<<','<<f[i].b<<','<<f[i].c<<'\n';put(path/"shape_vertices.csv",vertices.str());put(path/"shape_faces.csv",faces.str());std::vector<CsvRow>records;readArchiveCsv(path/"trials.csv",1,[&](CsvRow r){r["k"]="130";std::ostringstream n;n<<std::setprecision(17)<<volume;r["measured_V"]=n.str();r["canonical_com_x"]=r["canonical_com_y"]=r["canonical_com_z"]="0";records.push_back(r);});rows(path/"trials.csv",records);
    auto before=physicsUpdateCount();auto archive=openResultArchive(path);auto geometry=archive->scene(1);check(geometry->shape.vertices.size()==130&&geometry->shape.faces.size()==256&&physicsUpdateCount()==before,"read-only display reused numeric k/faces limit");std::cout<<"R2 actual 130-vertex/256-face archive opens without sampling/integration PASS\n";
}

}
int main(int argc,char**argv){try{JoltRuntime runtime;std::cout<<std::unitbuf;auto root=std::filesystem::temp_directory_path()/L"rs3d archive 中文 空格";std::filesystem::create_directories(root);
    if(argc>1){auto path=std::filesystem::u8path(argv[1]);auto s=loadScene(path/"scene.ini");auto c=freezeConfig(s);auto e=readFirstContacts(path,c->barrier,s.count,s.contactCell);FirstContactAccumulator aggregate(c->barrier,s.count,s.contactCell);for(const auto&event:e)aggregate.finish(event);auto d=readMotionDirectory(path,s.count);std::uint64_t frames=0;for(const auto&t:d->trials){for(const auto&block:t->blocks)frames+=readMotionBlock(*d,block).size();}check(e.size()==s.count&&d->trials.size()==s.count,"demo missing trial");std::cout<<"real demo roundtrip N="<<s.count<<" B="<<aggregate.hitTrials()<<" M="<<aggregate.missTrials()<<" unknown="<<aggregate.unknown()<<" frames="<<frames<<'\n';return 0;}
    SceneDraft s;s.count=3;s.terrain.type=TerrainType::flat;s.terrain.flatLength=50;s.terrain.width=20;s.barrier.enabled=true;s.barrierAutoX=s.barrierAutoZ=false;s.barrier.center={20,0,5};s.barrier.width=20;s.barrier.height=10;s.barrier.restitution=.9;s.barrier.friction=0;s.properties[velocityX]={50,50};s.properties[frictionValue]={0,0};s.properties[dragValue]={0,0};s.properties[rollingValue]={0,0};s.maxTime=5;s.trajectoryStride=0;s.outputRoot=root;
    BatchControl control;auto first=runBatch(freezeConfig(s),control);check(first.status==BatchStatus::complete,"real hit batch failed");check(first.contact.hitTrials()>0&&first.contact.known()==3,"ordinary real hits degraded to unknown");checkArchive(first);check(read(first.directory/"trajectory.csv").find('\n')==read(first.directory/"trajectory.csv").size()-1,"stride=0 wrote ordinary CSV rows");
    BatchOptions preview;preview.preview=2;std::uint64_t latestVersion=0;preview.observer=[&](const BatchEvent&e){if(e.analysis){check(e.analysis->version>latestVersion&&e.analysis->directory->trials.size()==3,"analysis directory not monotonic/complete");latestVersion=e.analysis->version;}};BatchControl pc;s.history.interval=.02;auto second=runBatch(freezeConfig(s),pc,preview);same(first,second);checkArchive(second);check(first.config->hash==second.config->hash&&first.config->recordingHash!=second.config->recordingHash,"display recording interval changes physical identity");
    s.history.enabled=false;BatchControl disabled;auto off=runBatch(freezeConfig(s),disabled);same(first,off);checkArchive(off);auto empty=readMotionDirectory(off.directory,3);for(auto&t:empty->trials)check(t->frames==0,"disabled history contains frames");
    compatible(s,root);
    auto corrupted=root/"corrupted_contact";std::filesystem::create_directories(corrupted);std::map<std::string,std::ofstream> corruptFiles;auto write=[&](const std::string&name,const std::string&text){auto&f=corruptFiles[name];if(!f.is_open())f.open(corrupted/name,std::ios::binary|std::ios::trunc);f<<text;};writeAnalysisHeaders(write);for(auto event:first.contacts){auto changed=*event;if(!changed.points.empty())changed.points.front().local.y+=.1;writeFirstContact(changed,write);}for(auto&f:corruptFiles)f.second.close();rejects([&]{readFirstContacts(corrupted,first.config->barrier,3,1);});
    auto missing=root/"missing_registered";std::filesystem::create_directories(missing);{std::ofstream marker(missing/"FILES_COMPLETE.txt");for(auto file:resultFiles)marker<<file.name<<'\n';}rejects([&]{validateResultFiles(missing,3);});
    BatchOptions cancel;cancel.preview=2;BatchControl cancelControl;cancel.observer=[&](const BatchEvent&e){if(e.kind==BatchEventKind::snapshot)cancelControl.cancel();};s.history.enabled=true;auto cancelled=runBatch(freezeConfig(s),cancelControl,cancel);check(cancelled.status==BatchStatus::cancelled&&cancelled.contact.unknown()==3,"cancelled contact counts claimed exact");checkArchive(cancelled);
    // All registered files, then the completion marker and final rename. Even
    // failures after probability serialization must invalidate both old/new grids.
    auto failureDraft=s;failureDraft.automaticGrid=false;failureDraft.automaticCollector=false;failureDraft.collectorX=.5;auto config=freezeConfig(failureDraft);std::vector<std::string> names;for(auto f:resultFiles)names.push_back(f.name);names.push_back("FILES_COMPLETE.txt");names.push_back("rename");
    for(const auto&name:names){BatchOptions options;options.faults.outputFailureAt=name;BatchControl stopped;stopped.cancel();auto result=runBatch(config,stopped,options);check(result.status==BatchStatus::ioError&&result.directory.extension()==L".pending","fault published successful transaction");check(!std::filesystem::exists(result.directory/"FILES_COMPLETE.txt")&&std::filesystem::exists(result.directory/"INCOMPLETE.txt"),"failed completion marker retained");auto manifest=read(result.directory/"manifest.ini");check(manifest.find("files_complete=0")!=manifest.npos&&manifest.find("contact_analysis_complete=0")!=manifest.npos,"io_error manifest claims complete");for(auto file:resultFiles)if(file.probability&&std::filesystem::exists(result.directory/file.name))check(read(result.directory/file.name)=="io_error_no_formal_probability\n","failure leaves valid probability table");std::cout<<"injection "<<name<<" PASS\n";}
    std::cout<<"R1/R2/R4 H2 C5/C6 preview=0/2, history on/off, intervals, events with stride=0, all-file transactions PASS\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
